const UPI_ID='7081201212@fam';
function checkout(){if(!lines().length)return;closeModal();go('checkout')}
function paymentPage(){if(!lines().length)return '<h1>YOUR CART IS EMPTY</h1><button class="btn-primary" data-view="shop">EXPLORE FIGURES</button>';return `<p class="trust-proof">CART → DELIVERY → PAYMENT</p><h1>COMPLETE YOUR ORDER</h1><form onsubmit="placeOrder(event)" class="payment-layout"><div><section class="payment-box"><h2>01 · Delivery details</h2><div class="ak-form">${fields()}</div></section><section class="payment-box"><h2>02 · Payment method</h2><label class="payment-option"><input type="radio" name="payment" value="cod" checked onchange="selectPayment(this.value)"><span><strong>Cash on Delivery</strong><small>Pay when your order arrives, after the seller confirms delivery availability.</small></span><b>COD</b></label><label class="payment-option"><input type="radio" name="payment" value="upi" onchange="selectPayment(this.value)"><span><strong>UPI payment</strong><small>Use any compatible UPI app.</small></span><b>UPI</b></label><div id="upi-panel" hidden><p>Pay to this UPI ID</p><div class="upi-address"><strong>${UPI_ID}</strong><button class="btn-outline" type="button" onclick="copyUpi()">COPY ID</button></div><p>Amount: <strong>${INR(totals().total)}</strong></p><div style="text-align:center;margin:22px 0"><img src="data:image/svg+xml;base64," alt="Scan to pay Anime Kingdom at 7081201212@fam using UPI" width="280" height="280" style="display:block;background:white;border:12px solid white;border-radius:12px;margin:0 auto;max-width:100%;height:auto"><p><strong>SCAN & PAY WITH UPI</strong><br>Enter the checkout total shown above in your UPI app.</p></div><a class="btn-primary" href="${E('upi://pay?pa='+encodeURIComponent(UPI_ID)+'&pn=Anime%20Kingdom&am='+totals().total.toFixed(2)+'&cu=INR&tn=Anime%20Kingdom%20order')}">OPEN UPI APP ↗</a><p class="form-help">Verify the recipient in your UPI app before approving. Opening the app does not confirm payment. On desktop, enter the ID and amount in your phone’s UPI app.</p><label class="payment-reference">UTR / UPI transaction number<input id="upi-utr" name="upiReference" inputmode="numeric" pattern="[0-9]{12}" maxlength="12" placeholder="12-digit UTR from your UPI app" disabled></label><label class="payment-reference">Payment screenshot<input id="upi-proof" name="upiScreenshot" type="file" accept="image/png,image/jpeg,image/webp" onchange="previewPaymentProof(this)" disabled></label><p class="form-help">Upload a PNG, JPG or WebP image (maximum 2 MB). Your UTR and screenshot are saved on this device only.</p><img id="upi-proof-preview" hidden alt="Selected payment screenshot" style="max-width:100%;max-height:300px;border-radius:8px"><p class="form-help">Payment stays unverified until the seller checks it. A reference number is not proof of payment.</p></div></section></div><aside class="payment-box payment-summary"><h2>Order summary</h2>${lines().map(({p,qty})=>`<article class="cart-row"><img src="${photo(p)}" alt="${E(p.name)}"><div><h3>${E(p.name)}</h3><p>Qty ${qty}</p></div><strong>${INR(p.price*qty)}</strong></article>`).join('')}${summary()}<p class="form-help">This standalone file saves your order on this device only. It does not send it to the seller or arrange delivery. Confirm the order and amount with the seller before transferring money.</p><button class="btn-primary" style="width:100%" id="payment-submit">SAVE COD ORDER</button><button type="button" class="text-button" onclick="openCart()">Edit cart</button></aside></form>`}
function selectPayment(method){for(const id of ['upi-utr','upi-proof']){$(id).disabled=method!=='upi';$(id).required=method==='upi'}$('upi-panel').hidden=method!=='upi';$('payment-submit').textContent=method==='upi'?'SAVE ORDER · VERIFICATION PENDING':'SAVE COD ORDER'}
async function copyUpi(){try{await navigator.clipboard.writeText(UPI_ID);toast('UPI ID copied.')}catch{toast('Copy this UPI ID: '+UPI_ID)}}
async function placeOrder(e){e.preventDefault();const list=lines();if(!list.length)return;if(list.some(({p,qty})=>qty>p.stock)){toast('Update your cart: stock has changed.');return}const values=Object.fromEntries(new FormData(e.target));const method=values.payment||'cod';if(!['cod','upi'].includes(method))return;const reference=method==='upi'?String(values.upiReference||'').trim():'';let proof='';if(method==='upi'){if(!/^[0-9]{12}$/.test(reference)){toast('Enter the 12-digit UTR from your UPI app.');return}try{proof=await paymentProof(values.upiScreenshot)}catch(error){toast(error.message);return}if(!lines().length)return}delete values.payment;delete values.upiReference;delete values.upiScreenshot;const order={id:'AK-'+Date.now().toString(36).toUpperCase(),date:new Date().toISOString(),address:values,paymentMethod:method,paymentStatus:method==='upi'?'Awaiting manual verification':'Due on delivery',upiId:method==='upi'?UPI_ID:'',upiReference:reference,paymentScreenshot:proof,items:list.map(({p,qty})=>({id:p.id,name:p.name,price:p.price,qty})),...totals(),status:'Order Placed'};const before=structuredClone(state);list.forEach(({p,qty})=>p.stock-=qty);state.orders.unshift(order);state.cart={};try{localStorage.setItem(KEY,JSON.stringify(state))}catch{state=before;toast('Not enough browser storage. Choose a smaller screenshot and try again.');return}coupon='';badge();go('orders');toast('Order saved on this device. Seller confirmation required.')}
